pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, bytes32 guessArg, uint256 warpBlocks) public {
        vm.assume(actor != address(0));
        vm.assume(warpBlocks >= 1 && warpBlocks <= 256);
        vm.deal(actor, 1 ether);
        // deploy contract already has 1 ether from constructor, but we need actor to lock
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessArg);
        // advance blocks to allow settle
        vm.roll(block.number + warpBlocks);
        uint256 balBefore = address(actor).balance;
        vm.prank(actor);
        try c.settle() { } catch { }
        uint256 balAfter = address(actor).balance;
        // In the reference, if guessArg == keccak256(blockhash of stored block) then actor gets 2 ether.
        // If guessArg != that hash, actor gets nothing.
        // In the bug, stored guess is bytes32(0), so actor gets 2 ether only if bytes32(0) == keccak256(...).
        // For any guessArg, the outcome (balance change) must be consistent with the stored guess.
        bytes32 expectedHash = keccak256(abi.encodePacked(blockhash(block.number - warpBlocks)));
        if (guessArg == expectedHash) {
            // reference must pay 2 ether, bug does not (unless expectedHash == bytes32(0))
            if (expectedHash != bytes32(0)) {
                assertTrue(balAfter == balBefore + 2 ether);
            } else {
                // both pay, no difference to detect, skip
                assertTrue(true);
            }
        } else {
            // reference does not pay, bug pays only if bytes32(0) == expectedHash
            if (expectedHash == bytes32(0)) {
                // bug pays but reference does not -> different
                assertTrue(balAfter == balBefore);
            } else {
                // neither pays
                assertTrue(balAfter == balBefore);
            }
        }
    }
}

